/bin/bash -lc "python - <<'PY'
import sim, numpy as np
h=sim.Sim().home_ctrl()

def eval_policy(hp_base=20,hk_base=20,hp_b=35,hk_b=20,start=300,dur=100,steps=3000):
    s=sim.Sim();
    c=h.copy();
    xs=[];zs=[];tu=[]
    cp=[False,False,False]
    for t in range(steps):
        if t<start:
            c[2]=hp_base; c[7]=hp_base; c[3]=hk_base; c[8]=hk_base
        elif t<start+dur:
            c[2]=hp_b; c[7]=hp_b; c[3]=hk_b; c[8]=hk_b
        else:
            c[2]=hp_base; c[7]=hp_base; c[3]=hk_base; c[8]=hk_base
        # other actuators zero-ish
        c[4]=-0.4; c[9]=-0.4
        c[10]=0
        s.data.ctrl[:] = c
        s.step()
        x=s.pelvis_position()[0]; z=s.pelvis_position()[2]; u=s.torso_up()
        xs.append(x); zs.append(z); tu.append(u)
        if not cp[0] and x>=0.18: cp[0]=True
        if not cp[1] and x>=0.34: cp[1]=True
        if not cp[2] and x>=0.45: cp[2]=True
    xfin=xs[-1]
    stable=((np.array(zs)>=0.23)&(np.array(tu)>=0.55)).mean()
    cpnum=sum(cp)
    return xfin, min(zs), min(tu), stable, cpnum, cp, xs[-500:]

best=[]
for hp_b in [22,24,26,28,30,32,34,36,38,40]:
  for hk_b in [10,20,30,40,50]:
    for start in [200,300,400,500,700,900]:
      for dur in [50,100,150,200]:
        xfin,zmin,tumin,st,cpnum,cp,last=eval_policy(hp_b=hp_b,hk_b=hk_b,start=start,dur=dur)
        # require some safety and not falling
        if zmin>0.2:
            best.append((xfin,cpnum,st,zmin,tumin,cp,hp_b,hk_b,start,dur))

best=sorted(best, key=lambda v:v[0], reverse=True)
for v in best[:40]:
    print(v)
PY"
